import re
html = open('/sessions/stoic-relaxed-carson/mnt/outputs/design-compare.html').read()
# Count cards per section using the actual class name 'oc'
for i in range(1, 21):
    if i < 20:
        match = re.search(rf'id=\"s{i}\".*?(?=id=\"s{i+1}\")', html, re.DOTALL)
    else:
        match = re.search(rf'id=\"s{i}\".*?</body>', html, re.DOTALL)
    if match:
        cards = len(re.findall(r'class=\"oc\"', match.group()))
        print(f'Section {i}: {cards} cards')
    else:
        print(f'Section {i}: NOT FOUND')
"

