// Capture all computed styles and content from the access code page
const body = document.body;
const all = document.querySelectorAll('*');
const styles = {};
const texts = [];

// Get key elements and their styles
all.forEach((el, i) => {
  const cs = getComputedStyle(el);
  const text = el.innerText?.trim()?.substring(0, 100);
  if (text && text.length > 2) {
    texts.push({tag: el.tagName, class: el.className?.substring(0,80), text: text.substring(0,80)});
  }
});

// Get body background
const bodyCS = getComputedStyle(body);
const result = {
  bodyBg: bodyCS.backgroundColor,
  bodyFont: bodyCS.fontFamily,
  bodyColor: bodyCS.color,
  pageTitle: document.title,
  url: window.location.href,
  uniqueTexts: texts.filter((t, i) => texts.findIndex(x => x.text === t.text) === i).slice(0, 30)
};
JSON.stringify(result, null, 2);

