tabButtons.forEach(button => {
    button.addEventListener('click', () => {
        const tabId = button.getAttribute('data-tab');

        // Remove active class from all tabs and buttons
        tabButtons.forEach(btn => btn.classList.remove('active'));
        tabContents.forEach(content => content.classList.remove('active'));

        // Add active class to clicked button and corresponding tab
        button.classList.add('active');
        document.getElementById(tabId).classList.add('active');
    });
});

// ==================== DESIGN CONTROL HANDLERS ====================
const controls = {
    headingFont: document.getElementById('headingFont'),
    bodyFont: document.getElementById('bodyFont'),
    monoFont: document.getElementById('monoFont'),
    accentColor: document.getElementById('accentColor'),
    bgColor: document.getElementById('bgColor'),
    cardBgColor: document.getElementById('cardBgColor'),
    textColor: document.getElementById('textColor'),
    secondaryText: document.getElementById('secondaryText'),
    borderRadius: document.getElementById('borderRadius'),
    buttonStyle: document.getElementById('buttonStyle'),
    progressStyle: document.getElementById('progressStyle'),
    scoreStyle: document.getElementById('scoreStyle'),
    badgeStyle: document.getElementById('badgeStyle'),
    issueCardBorder: document.getElementById('issueCardBorder')
};

// Font control handlers
controls.headingFont.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--heading-font', e.target.value);
});

controls.bodyFont.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--body-font', e.target.value);
});

controls.monoFont.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--mono-font', e.target.value);
});

// Color control handlers
controls.accentColor.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--accent-gold', e.target.value);
});

controls.bgColor.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--bg-body', e.target.value);
});

controls.cardBgColor.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--bg-card', e.target.value);
});

controls.textColor.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--text-primary', e.target.value);
});

controls.secondaryText.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--text-secondary', e.target.value);
});

// Border radius handler
controls.borderRadius.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--border-radius', e.target.value);
});

// Style control handlers
controls.buttonStyle.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--button-style', e.target.value);
    applyButtonStyles(e.target.value);
});

controls.progressStyle.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--progress-style', e.target.value);
    applyProgressStyles(e.target.value);
});

controls.scoreStyle.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--score-style', e.target.value);
    applyScoreStyles(e.target.value);
});

controls.badgeStyle.addEventListener('change', (e) => {
    document.documentElement.style.setProperty('--badge-style', e.target.value);
    applyBadgeStyles(e.target.value);
});

