        controls.issueCardBorder.addEventListener('change', (e) => {
            document.documentElement.style.setProperty('--issue-border-style', e.target.value);
            applyIssueCardStyles(e.target.value);
        });

        // ==================== STYLE APPLICATION FUNCTIONS ====================
        function applyButtonStyles(style) {
            const btns = document.querySelectorAll('.btn-primary');
            btns.forEach(btn => {
                // Reset classes
                btn.classList.remove('gold-outline', 'white-filled', 'dark-filled', 'gradient');

                if (style === 'gold-outline') {
                    btn.style.backgroundColor = 'transparent';
                    btn.style.border = '2px solid var(--accent-gold)';
                    btn.style.color = 'var(--accent-gold)';
                } else if (style === 'white-filled') {
                    btn.style.backgroundColor = 'var(--text-primary)';
                    btn.style.border = 'none';
                    btn.style.color = 'var(--bg-body)';
                } else if (style === 'dark-filled') {
                    btn.style.backgroundColor = 'rgba(255,255,255,0.15)';
                    btn.style.border = 'none';
                    btn.style.color = 'var(--text-primary)';
                } else if (style === 'gold-gradient') {
                    btn.style.background = 'linear-gradient(135deg, var(--accent-gold), rgba(201,169,110,0.7))';
                    btn.style.border = 'none';
                    btn.style.color = 'var(--bg-body)';
                } else if (style === 'minimal-underline') {
                    btn.style.backgroundColor = 'transparent';
                    btn.style.border = 'none';
                    btn.style.borderBottom = '2px solid var(--accent-gold)';
                    btn.style.color = 'var(--accent-gold)';
                    btn.style.borderRadius = '0';
                } else if (style === 'pill-shape') {
                    btn.style.backgroundColor = 'var(--accent-gold)';
                    btn.style.border = 'none';
                    btn.style.color = 'var(--bg-body)';
                    btn.style.borderRadius = '50px';
                } else if (style === 'sharp-rectangle') {
                    btn.style.backgroundColor = 'var(--accent-gold)';
                    btn.style.border = 'none';
                    btn.style.color = 'var(--bg-body)';
                    btn.style.borderRadius = '0';
                } else {
                    // gold-filled (default)
                    btn.style.backgroundColor = 'var(--accent-gold)';
                    btn.style.border = 'none';
                    btn.style.color = 'var(--bg-body)';
                    btn.style.borderRadius = 'var(--border-radius)';
                }
            });
        }

        function applyProgressStyles(style) {
            const bars = document.querySelectorAll('.progress-fill');
            bars.forEach(bar => {
                if (style === 'solid-green') {
                    bar.style.background = 'solid var(--color-green)';
                } else if (style === 'gold-accent') {
                    bar.style.background = 'var(--accent-gold)';
                } else if (style === 'thin-line') {
                    bar.parentElement.style.height = '2px';
                    bar.style.background = 'var(--color-green)';
                } else if (style === 'segmented') {
                    bar.style.background = 'repeating-linear-gradient(90deg, var(--color-green) 0px, var(--color-green) 10px, transparent 10px, transparent 12px)';
                } else if (style === 'rounded-pill') {
                    bar.parentElement.style.borderRadius = '10px';
                    bar.style.background = 'var(--color-green)';
                } else if (style === 'flat-gray-green') {
                    bar.parentElement.style.backgroundColor = 'rgba(136,136,136,0.2)';
                    bar.style.background = 'var(--color-green)';
                } else if (style === 'striped') {
                    bar.style.background = 'repeating-linear-gradient(45deg, var(--color-green) 0px, var(--color-green) 10px, rgba(46,204,113,0.6) 10px, rgba(46,204,113,0.6) 20px)';
                } else {
                    // green-gradient (default)
                    bar.style.background = 'linear-gradient(90deg, var(--color-green), var(--color-green))';
                    bar.parentElement.style.height = '8px';
                }
            });
        }

        function applyScoreStyles(style) {
            const circles = document.querySelectorAll('.score-circle');
            circles.forEach(circle => {
                const number = circle.querySelector('.score-number');
                if (style === 'large-mono') {
                    circle.style.background = 'transparent';
                    number.style.fontSize = '4rem';
                    circle.style.width = 'auto';
                    circle.style.height = 'auto';
                } else if (style === 'gold-ring') {
                    circle.style.background = 'conic-gradient(var(--accent-gold) 0deg 342deg, rgba(201,169,110,0.2) 342deg)';
                    number.style.color = 'var(--accent-gold)';
                } else if (style === 'thin-ring') {
                    circle.style.background = 'conic-gradient(var(--color-green) 0deg 342deg, rgba(46,204,113,0.1) 342deg)';
                    circle.style.border = '2px solid var(--color-green)';
                } else if (style === 'donut') {
                    circle.style.borderRadius = '50%';
                    circle.style.background = 'conic-gradient(var(--color-green) 0deg 342deg, rgba(0,0,0,0.2) 342deg)';
                } else if (style === 'square-badge') {
                    circle.style.borderRadius = 'var(--border-radius)';
                    circle.style.width = '140px';
                    circle.style.height = '140px';
                } else if (style === 'serif-number') {
                    number.style.fontFamily = 'var(--heading-font)';
                    number.style.fontWeight = '700';
                } else if (style === 'gradient-ring') {
                    circle.style.background = 'conic-gradient(var(--accent-gold) 0deg 171deg, var(--color-green) 171deg 342deg, rgba(200,150,80,0.2) 342deg)';
                } else {
                    // green-ring (default)
                    circle.style.background = 'conic-gradient(var(--color-green) 0deg 342deg, rgba(46,204,113,0.2) 342deg)';
                    circle.style.border = 'none';
                    circle.style.borderRadius = '50%';
                    circle.style.width = '120px';
                    circle.style.height = '120px';
                    number.style.fontSize = '2.5rem';
                    number.style.color = 'var(--color-green)';
                    number.style.fontFamily = 'var(--heading-font)';
                }
            });
        }

        function applyBadgeStyles(style) {
            const badges = document.querySelectorAll('.badge, .pass-badge, .status-badge, .section-badge');
            badges.forEach(badge => {
                if (style === 'outlined-pill') {
                    badge.style.backgroundColor = 'transparent';
                    badge.style.border = '1px solid currentColor';
                } else if (style === 'square-tag') {
                    badge.style.borderRadius = 'var(--border-radius)';
                } else if (style === 'text-only') {
                    badge.style.backgroundColor = 'transparent';
                    badge.style.padding = '0';
                } else if (style === 'dot-text') {
                    badge.style.paddingLeft = '0.4rem';
                } else if (style === 'underline-accent') {
                    badge.style.backgroundColor = 'transparent';
                    badge.style.borderBottom = '2px solid currentColor';
                    badge.style.borderRadius = '0';
                } else if (style === 'filled-rect') {
                    badge.style.borderRadius = '2px';
                } else if (style === 'minimal-chip') {
                    badge.style.backgroundColor = 'rgba(201,169,110,0.1)';
                    badge.style.padding = '0.3rem 0.6rem';
                } else {
                    // colored-pill (default)
                    badge.style.borderRadius = '12px';
                    badge.style.border = 'none';
                }
            });
        }

        function applyIssueCardStyles(style) {
            const cards = document.querySelectorAll('.issue-card');
            cards.forEach(card => {
                // Reset styles
                card.style.borderLeft = 'none';
                card.style.border = 'none';
                card.style.borderTop = 'none';
                card.style.boxShadow = 'none';
                card.style.position = 'relative';

                if (style === 'full-border') {
                    card.style.border = '2px solid var(--color-orange)';
                } else if (style === 'top-line') {
                    card.style.borderTop = '4px solid var(--color-orange)';
                    card.style.border = 'none';
                } else if (style === 'dashed-border') {
                    card.style.border = '2px dashed var(--color-orange)';
                } else if (style === 'shadow-only') {
                    card.style.boxShadow = '0 0 20px rgba(243,156,18,0.2)';
                } else if (style === 'glow') {
                    card.style.boxShadow = '0 0 30px rgba(243,156,18,0.4), inset 0 0 20px rgba(243,156,18,0.1)';
                    card.style.border = 'none';
                } else if (style === 'corner-accent') {
                    card.style.border = '1px solid rgba(243,156,18,0.3)';
                    card.style.borderRadius = 'var(--border-radius)';
                    card.style.position = 'relative';
                    // Would need pseudo-element for true corner accent
                } else if (style === 'double-line') {
                    card.style.borderLeft = '4px double var(--color-orange)';
                } else {
                    // left-bar (default)
                    card.style.borderLeft = '4px solid var(--color-orange)';
                }
            });
        }

        // Initialize styles on load
        applyButtonStyles('gold-filled');
        applyProgressStyles('green-gradient');
        applyScoreStyles('green-ring');
        applyBadgeStyles('colored-pill');
        applyIssueCardStyles('left-bar');
    </script>
</body>
</html>

